export type ParsedInitMarketTwoInstruction<
  TProgram extends string = typeof EXPONENT_CORE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    adminSigner: TAccountMetas[1];
    /** There is 1 market per vault */
    market: TAccountMetas[2];
    /** Links the mint_sy & mint_pt & sy_program together */
    vault: TAccountMetas[3];
    mintSy: TAccountMetas[4];
    mintPt: TAccountMetas[5];
    mintLp: TAccountMetas[6];
    escrowPt: TAccountMetas[7];
    /**
     * This account for SY is only a temporary pass-through account
     * It is used to transfer SY tokens from the signer to the market
     * And then from the market to the SY program's escrow
     */
    escrowSy: TAccountMetas[8];
    /** Holds activated LP tokens for farming & SY emissions */
    escrowLp: TAccountMetas[9];
    /** Signer's PT token account */
    ptSrc: TAccountMetas[10];
    /** Signer's SY token account */
    sySrc: TAccountMetas[11];
    /** Receiving account for LP tokens */
    lpDst: TAccountMetas[12];
    /** Use the old Token program as the implementation for PT & SY & LP tokens */
    tokenProgram: TAccountMetas[13];
    systemProgram: TAccountMetas[14];
    syProgram: TAccountMetas[15];
    associatedTokenProgram: TAccountMetas[16];
    addressLookupTable: TAccountMetas[17];
    admin: TAccountMetas[18];
    tokenTreasuryFeeSy: TAccountMetas[19];
  };
  data: InitMarketTwoInstructionData;
};

export function parseInitMarketTwoInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedInitMarketTwoInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 20) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 20,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      adminSigner: getNextAccount(),
      market: getNextAccount(),
      vault: getNextAccount(),
      mintSy: getNextAccount(),
      mintPt: getNextAccount(),
      mintLp: getNextAccount(),
      escrowPt: getNextAccount(),
      escrowSy: getNextAccount(),
      escrowLp: getNextAccount(),
      ptSrc: getNextAccount(),
      sySrc: getNextAccount(),
      lpDst: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      syProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      addressLookupTable: getNextAccount(),
      admin: getNextAccount(),
      tokenTreasuryFeeSy: getNextAccount(),
    },
    data: getInitMarketTwoInstructionDataDecoder().decode(instruction.data),
  };
}
